function heldRefs(world) {
  world.__heldRefs = world.__heldRefs || {};
  return world.__heldRefs;
}

// Capture the live DOM element so we can later assert the app mutated it in place
// rather than replacing it. happy-dom keeps element identity across a mutation, so a
// reference taken before the change must still be the same node afterwards.
Given('I hold a reference to the todo {string} element', function (name) {
  const li = findTodoLiByIdentity(this, name);
  if (!li) throw new Error(`step: no todo element for "${name}" to hold a reference to`);
  heldRefs(this)[name] = li;
});

Then('the todo {string} element is the same element as the held reference', function (name) {
  const held = heldRefs(this)[name];
  if (!held) throw new Error(`step: no held reference for todo "${name}"`);
  const current = findTodoLiByIdentity(this, name);
  if (!current) throw new Error(`step: no current todo element for "${name}"`);
  if (current !== held) {
    throw new Error(
      `todo "${name}" element changed: the held reference is not the same DOM element ` +
      '(the list was rebuilt instead of mutated in place)',
    );
  }
});

Then('the toggle control of the todo {string} is not visible', function (name) {
  const li = findTodoLiByIdentity(this, name);
  if (!li) throw new Error(`step: no todo with title "${name}"`);
  const toggle = li.querySelector('.toggle');
  if (!toggle) throw new Error(`step: todo "${name}" has no toggle control`);
  const display = this.window.getComputedStyle(toggle).display;
  if (display !== 'none') {
    throw new Error(`toggle control of todo "${name}" is visible (display: "${display}")`);
  }
});

Then('the label of the todo {string} is not visible', function (name) {
  const li = findTodoLiByIdentity(this, name);
  if (!li) throw new Error(`step: no todo with title "${name}"`);
  const label = li.querySelector('label');
  if (!label) throw new Error(`step: todo "${name}" has no label`);
  const display = this.window.getComputedStyle(label).display;
  if (display !== 'none') {
    throw new Error(`label of todo "${name}" is visible (display: "${display}")`);
  }
});

// ---- Conformance support: completion-toggle seam structural check -----------
//
// The @conformance scenario attests the project's own method: the completion-toggle
// seams must preserve the toggled element's identity by mutating it in place, and
// must not rebuild the todo list on a same-visibility completion toggle.
//
// This is a structural conformance check over the real production source, owned by
// QM as verification support (per the Scantling agreement: a bespoke checker for a
// constraint no independent tool expresses). It reads js/app.js and inspects the
// completeTodo and toggleAllTodos seams by exact name — real structure, not a spy.

function readAppSource(relPath) {
  const full = path.resolve(__dirname, '..', '..', relPath);
  if (!fs.existsSync(full)) throw new Error(`conformance: ${relPath} does not exist`);
  return fs.readFileSync(full, 'utf8');
}

// Balance braces from a named function's opening brace, while ignoring braces that
// live inside string literals or line comments, so the extracted seam is the real
// function body even when its template strings carry quote characters.
function extractSeam(src, name) {
  const start = src.search(new RegExp('function\\s+' + name + '\\s*\\('));
  if (start === -1) throw new Error(`conformance: no seam named ${name} in js/app.js`);
  const open = src.indexOf('{', start);
  let depth = 0;
  let inStr = null;
  let inLineComment = false;
  for (let i = open; i < src.length; i++) {
    const c = src[i];
    if (inLineComment) { if (c === '\n') inLineComment = false; continue; }
    if (inStr) { if (c === inStr && src[i - 1] !== '\\') inStr = null; continue; }
    if (c === '/' && src[i + 1] === '/') { inLineComment = true; continue; }
    if (c === "'" || c === '"' || c === '`') { inStr = c; continue; }
    if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) { return src.slice(open, i + 1); } }
  }
  throw new Error(`conformance: unterminated seam ${name}`);
}

Given('the completion-toggle source in {string}', function (relPath) {
  this._toggleSource = readAppSource(relPath);
  this._toggleSourcePath = relPath;
});

When('the structural conformance check inspects the completeTodo and toggleAllTodos seams', function () {
  const src = this._toggleSource;
  this._toggleSeams = {
    completeTodo: extractSeam(src, 'completeTodo'),
    toggleAllTodos: extractSeam(src, 'toggleAllTodos'),
  };
});

Then('neither seam rebuilds the todo list when a completion toggle leaves the item visible', function () {
  const seams = this._toggleSeams;
  const problems = [];
  for (const [name, body] of Object.entries(seams)) {
    // A same-visibility toggle must mutate the existing element in place rather than
    // rebuild. The rebuild primitive is a direct rewrite of the list container, or a
    // renderList() delegation. renderList() is permitted only on the alternate
    // (visibility-changing) branch, i.e. guarded by `else`, so the same-visibility
    // path never takes it.
    if (/todoList\.innerHTML\s*=/.test(body)) {
      problems.push(`${name} rebuilds the todo list directly via todoList.innerHTML`);
    }
    if (/renderList\s*\(\s*\)/.test(body) && !/\belse\b/.test(body)) {
      problems.push(
        `${name} rebuilds the todo list via renderList() on a path a same-visibility toggle can take`,
      );
    }
  }
  if (problems.length) throw new Error('conformance: ' + problems.join('; '));
});

Then('each seam mutates the toggled list element\'s completed class and its toggle checked state in place', function () {
  const seams = this._toggleSeams;
  const problems = [];
  for (const [name, body] of Object.entries(seams)) {
    const mutatesClass = /classList\.(toggle|add|remove)\(\s*['"]?completed/.test(body);
    const mutatesToggle = /\.checked\s*=/.test(body);
    if (!mutatesClass) problems.push(`${name} does not mutate the completed class in place`);
    if (!mutatesToggle) problems.push(`${name} does not mutate the toggle checked state in place`);
  }
  if (problems.length) throw new Error('conformance: ' + problems.join('; '));
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    if (this.window) this.window = undefined;
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;
    this._boot();
  }

  // Reload on the SAME window. happy-dom keeps localStorage and location.hash per Window
  // instance (a fresh Window starts empty), so a real reload that preserves the user's
  // persisted todos and active filter must reuse the live window rather than build a new
  // one. The document is re-written and the app re-evaluated, but the window's persisted
  // state survives the reload.
  reloadApp() {
    if (!this.window) throw new Error('verification support: reloadApp() before the app was loaded');
    this.document = this.window.document;
    this._boot();
  }

  _boot() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    if (!w.__ssRouterAdded) {
      this.document.addEventListener('click', (e) => {
        const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
        if (!a) return;
        const next = a.getAttribute('href');
        if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
      }, true);
      w.__ssRouterAdded = true;
    }
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

